-- Run once in the Supabase SQL Editor.
-- Seeds 5 curated roadmap templates for each of Likhora AI's 7 onboarding
-- business categories (35 total) into public.community_posts, so the
-- Community tab has real, useful starting content instead of a single
-- example row.
--
-- Safe to re-run: uses ON CONFLICT on (author_id, business_name), so running
-- this again after editing a template just updates it in place rather than
-- duplicating rows.

create unique index if not exists community_posts_author_business_unique
  on public.community_posts (author_id, business_name);

insert into public.community_posts
  (author_id, author_name, business_name, business_type, location, summary, image_url, template_data)
values

